window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_mathematics_de"]=window.LC_CHUNKS["university_mathematics_de"]||{};window.LC_CHUNKS["university_mathematics_de"][7]={"university_mathematics_de:M7-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M7-L1 – Interpolation und Approximation<\/h1>\n<p><strong>Kursbereich:<\/strong> M7 – Numerik und Optimierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L2<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L3<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Numerische Vertiefung des gemeinsamen\nBachelor-Kerns<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du konstruierst ein Interpolationspolynom, leitest eine\nFehlerabschätzung her und unterscheidest Approximationsfehler,\nDatenfehler und Rundungsfehler. Du entscheidest, wann ein\nAusgleichsmodell geeigneter ist als exakte Interpolation.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Existenz, Eindeutigkeit und Lagrange-Basis<\/h2>\n<p>Seien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">x_0,\\dots,x_n<\/annotation><\/semantics><\/math>\npaarweise verschiedene reelle Stützstellen und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>y<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">y_i<\/annotation><\/semantics><\/math>\ndie zugehörigen Werte. Gesucht ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>∈<\/mo><msub><mi mathvariant=\"script\">𝒫<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">p\\in\\mathcal P_n<\/annotation><\/semantics><\/math>,\nalso ein Polynom vom Grad höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>,\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">p(x_i)=y_i<\/annotation><\/semantics><\/math>.\nSetze<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><munder><mo>∏<\/mo><mrow><mi>j<\/mi><mo>≠<\/mo><mi>i<\/mi><\/mrow><\/munder><mfrac><mrow><mi>x<\/mi><mo>−<\/mo><msub><mi>x<\/mi><mi>j<\/mi><\/msub><\/mrow><mrow><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>x<\/mi><mi>j<\/mi><\/msub><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><mi>n<\/mi><\/munderover><msub><mi>y<\/mi><mi>i<\/mi><\/msub><msub><mi>L<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L_i(x)=\\prod_{j\\ne i}\\frac{x-x_j}{x_i-x_j},\\qquad p(x)=\\sum_{i=0}^n y_iL_i(x).<\/annotation><\/semantics><\/math><\/p>\n<p>Wegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">L_i(x_j)=\\delta_{ij}<\/annotation><\/semantics><\/math>\nerfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nalle Bedingungen. Zwei Lösungen hätten eine Differenz vom Grad höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n+1<\/annotation><\/semantics><\/math>\nverschiedenen Nullstellen; diese Differenz ist daher das Nullpolynom.\nDas zeigt sowohl Existenz als auch Eindeutigkeit.<\/p>\n<p>Beispiel: Für die Punkte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-1,1),(0,0),(2,4)<\/annotation><\/semantics><\/math>\nsind die Daten Werte von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^2<\/annotation><\/semantics><\/math>.\nDie eindeutige Lösung lautet folglich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">p=x^2<\/annotation><\/semantics><\/math>,\nauch ohne Ausmultiplizieren. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,1),(1,2),(2,5)<\/annotation><\/semantics><\/math>\nerhältst du\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>1<\/mn><mo>+<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">p=1+x^2<\/annotation><\/semantics><\/math>.\nBei vielen Auswertungen ist eine baryzentrische Darstellung meist\ngünstiger als die direkte Produktform; die folgende Implementierung\ndient kleinen Lehrbeispielen.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> math <span class=\"im\">import<\/span> prod<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> lagrange(xs, ys, x):<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> <span class=\"kw\">not<\/span> xs <span class=\"kw\">or<\/span> <span class=\"bu\">len<\/span>(xs) <span class=\"op\">!=<\/span> <span class=\"bu\">len<\/span>(ys) <span class=\"kw\">or<\/span> <span class=\"bu\">len<\/span>(<span class=\"bu\">set<\/span>(xs)) <span class=\"op\">!=<\/span> <span class=\"bu\">len<\/span>(xs):<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;distinct nodes and matching data required&quot;<\/span>)<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> <span class=\"bu\">sum<\/span>(yi <span class=\"op\">*<\/span> prod((x<span class=\"op\">-<\/span>xj)<span class=\"op\">/<\/span>(xi<span class=\"op\">-<\/span>xj)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                        <span class=\"cf\">for<\/span> j, xj <span class=\"kw\">in<\/span> <span class=\"bu\">enumerate<\/span>(xs) <span class=\"cf\">if<\/span> j <span class=\"op\">!=<\/span> i)<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>               <span class=\"cf\">for<\/span> i, (xi, yi) <span class=\"kw\">in<\/span> <span class=\"bu\">enumerate<\/span>(<span class=\"bu\">zip<\/span>(xs, ys)))<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">assert<\/span> <span class=\"bu\">abs<\/span>(lagrange([<span class=\"dv\">0<\/span>, <span class=\"dv\">1<\/span>, <span class=\"dv\">2<\/span>], [<span class=\"dv\">1<\/span>, <span class=\"dv\">2<\/span>, <span class=\"dv\">5<\/span>], <span class=\"fl\">1.5<\/span>)<span class=\"op\">-<\/span><span class=\"fl\">3.25<\/span>) <span class=\"op\">&lt;<\/span> <span class=\"fl\">1e-12<\/span><\/span><\/code><\/pre><\/div>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Fehlerformel und Beweis<\/h2>\n<p>Wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>∈<\/mo><msup><mi>C<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f\\in C^{n+1}([a,b])<\/annotation><\/semantics><\/math>\nund alle Stützstellen sowie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nim Intervall liegen, gilt für einen Zwischenpunkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ξ<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\xi\\in(a,b)<\/annotation><\/semantics><\/math>\n(bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\naußerhalb der Stützstellen, aber im Intervall, auf deren gemeinsamer\nkonvexer Hülle)<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mrow><msup><mi>f<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ξ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>!<\/mi><\/mrow><\/mfrac><munderover><mo>∏<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><mi>n<\/mi><\/munderover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f(x)-p(x)=\\frac{f^{(n+1)}(\\xi)}{(n+1)!}\\prod_{i=0}^n(x-x_i).<\/annotation><\/semantics><\/math><\/p>\n<p>An Stützstellen ist der Fehler unmittelbar null. Für andere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nsetze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mo>∏<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>−<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\omega(t)=\\prod_i(t-x_i)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>ω<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">c=(f(x)-p(x))/\\omega(x)<\/annotation><\/semantics><\/math>.\nDie Funktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo>=<\/mo><mi>f<\/mi><mo>−<\/mo><mi>p<\/mi><mo>−<\/mo><mi>c<\/mi><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">g=f-p-c\\omega<\/annotation><\/semantics><\/math>\nhat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>+<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n+2<\/annotation><\/semantics><\/math>\nverschiedene Nullstellen. Wiederholte Anwendung des Satzes von Rolle\nliefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>g<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ξ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g^{(n+1)}(\\xi)=0<\/annotation><\/semantics><\/math>.\nDa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>p<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p^{(n+1)}=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>ω<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>!<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega^{(n+1)}=(n+1)!<\/annotation><\/semantics><\/math>,\nfolgt die Formel. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M<\/mi><mo>=<\/mo><msub><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">M=\\max_{[a,b]}|f^{(n+1)}|<\/annotation><\/semantics><\/math>\nergibt sich eine obere Schranke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>!<\/mi><\/mrow><annotation encoding=\"application/x-tex\">M|\\omega(x)|/(n+1)!<\/annotation><\/semantics><\/math>.<\/p>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>x<\/mi><mn>3<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f(x)=x^3<\/annotation><\/semantics><\/math>\nund Stützstellen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1,0,1<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p=x<\/annotation><\/semantics><\/math>\nund die Formel liefert exakt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mn>3<\/mn><\/msup><mo>−<\/mo><mi>x<\/mi><mo>=<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">x^3-x=x(x-1)(x+1)<\/annotation><\/semantics><\/math>.\nFür lineare Interpolation von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mi>x<\/mi><\/msup><annotation encoding=\"application/x-tex\">e^x<\/annotation><\/semantics><\/math>\nzwischen 0 und 1 beträgt die Schranke bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=1/2<\/annotation><\/semantics><\/math>\ngenau\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>e<\/mi><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e/8<\/annotation><\/semantics><\/math>.\nDer tatsächliche Fehler hat Betrag\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>e<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>−<\/mo><msqrt><mi>e<\/mi><\/msqrt><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2104<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(1+e)/2-\\sqrt e\\approx0{,}2104<\/annotation><\/semantics><\/math>\nund liegt darunter.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_035_DE.svg\"\nalt=\"Exponentialfunktion und lineares Interpolationspolynom mit Fehler am Mittelpunkt.\" />\n<figcaption aria-hidden=\"true\">Exponentialfunktion und lineares\nInterpolationspolynom mit Fehler am Mittelpunkt.<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Kondition, Stützstellen und Extrapolation<\/h2>\n<p>Eine Erhöhung des Polynomgrades bei äquidistanten Stützstellen\ngarantiert keine gleichmäßige Konvergenz. Die Runge-Funktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mn>25<\/mn><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">1/(1+25x^2)<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-1,1]<\/annotation><\/semantics><\/math>\nzeigt Randoszillationen. Die Nullstellen des Chebyshev-Polynoms\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>T<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><annotation encoding=\"application/x-tex\">T_{n+1}<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>i<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>π<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>n<\/mi><mo>+<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">x_i=\\cos((2i+1)\\pi/(2n+2))<\/annotation><\/semantics><\/math>,\nhäufen sich nahe den Rändern und verkleinern das maximale Betragsniveau\ndes monischen Stützstellenpolynoms. Das verbessert die Fehlerkontrolle,\nsofern die Ableitungsschranke geeignet ist. Alternativ zerlegt man das\nIntervall und verwendet stückweise Polynome niedrigen Grades.<\/p>\n<p>Bei Datenstörungen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mi>ε<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|\\Delta y_i|\\le\\varepsilon<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mi>ε<\/mi><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>L<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\Delta p(x)|\\le\\varepsilon\\sum_i|L_i(x)|<\/annotation><\/semantics><\/math>.\nDiese Verstärkung beschreibt die Kondition bezüglich der Daten,\nunabhängig von der Implementierung. Rundungsfehler entstehen zusätzlich\nbeim Rechnen. Außerhalb des Datenintervalls können sowohl das\nStützstellenprodukt als auch die Verstärkung wachsen: Extrapolation\nverlangt eine begründete Modellannahme, nicht nur eine Formel.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Ausgleich statt Interpolation<\/h2>\n<p>Bei verrauschten Messungen sollen nicht zwingend alle Datenpunkte\ngetroffen werden. Für die Gerade\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a+bx<\/annotation><\/semantics><\/math>\nminimiert die Methode der kleinsten Quadrate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\sum_i(a+bx_i-y_i)^2<\/annotation><\/semantics><\/math>.\nDie Ableitungen nach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a,b<\/annotation><\/semantics><\/math>\nergeben\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mo>∑<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mo>∑<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">ma+b\\sum x_i=\\sum y_i<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>∑<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>+<\/mo><mi>b<\/mi><mo>∑<\/mo><msubsup><mi>x<\/mi><mi>i<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><mo>∑<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><msub><mi>y<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">a\\sum x_i+b\\sum x_i^2=\\sum x_iy_i<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>m<\/mi><annotation encoding=\"application/x-tex\">m<\/annotation><\/semantics><\/math>\nMesswerte. Bei nicht konstanten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">x_i<\/annotation><\/semantics><\/math>\nist die Lösung eindeutig. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,1),(1,3),(2,2)<\/annotation><\/semantics><\/math>\nerhältst du\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">b=1/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=3/2<\/annotation><\/semantics><\/math>.\nDie Residuen (Modell minus Daten) sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2,-1,1/2<\/annotation><\/semantics><\/math>;\nihre Quadratsumme ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3/2<\/annotation><\/semantics><\/math>.\nDas quadratische Interpolationspolynom hätte Nullresiduen, aber daraus\nfolgt keine bessere Vorhersage. In größeren Problemen sind QR-Zerlegung\noder SVD numerisch oft günstiger als explizite Normalgleichungen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme das Interpolationspolynom für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>6<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,2),(1,3),(2,6)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Beweise die Eindeutigkeit für vier verschiedene Stützstellen.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Interpoliere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>3<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^3<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0,1,2<\/annotation><\/semantics><\/math>\nund bestimme den Fehler bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Bestimme eine Fehlerobergrenze für lineare Interpolation von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sin x<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,\\pi/2]<\/annotation><\/semantics><\/math>\nam Mittelpunkt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Bestimme die Ausgleichsgerade für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0,0),(1,2),(2,1)<\/annotation><\/semantics><\/math>\nund erkläre, warum sie nicht interpoliert.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mo>+<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">p(x)=2+x^2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Differenz hat Grad höchstens 3 und vier verschiedene\nNullstellen, ist also null.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>3<\/mn><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><mn>2<\/mn><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p=3x^2-2x<\/annotation><\/semantics><\/math>,\nFehler\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x(x-1)(x-2)=3/8<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mo>″<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|f&#39;&#39;|\\le1<\/annotation><\/semantics><\/math>,\ndaher\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>π<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>32<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\pi^2/32<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mi>b<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=1/2,b=1/2<\/annotation><\/semantics><\/math>;\nVorhersagen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2,1,3/2<\/annotation><\/semantics><\/math>\nstimmen nicht mit allen Daten überein.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://tobydriscoll.net/fnc-julia/globalapprox/polynomial.html\">Driscoll/Braun\n– Fundamentals of Numerical Computation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §9.1 · Zuletzt abgerufen:\n2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M7-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M7-L2 – Numerische Quadratur und Fehlerabschätzung<\/h1>\n<p><strong>Kursbereich:<\/strong> M7 – Numerik und Optimierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L3<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M7&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M7-L1<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Numerische Vertiefung des gemeinsamen\nBachelor-Kerns<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du leitest Quadraturregeln aus Polynominterpolation ab, wendest\nzusammengesetzte Trapez- und Simpsonregeln an, bestimmst Fehlergrenzen\nund konstruierst die Gaußregel mit zwei Knoten. Du unterscheidest\nPolynomexaktheit, Fehlerordnung und tatsächlichen Rechenfehler.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quadratur aus Interpolation<\/h2>\n<p>Die Quadratur approximiert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo>=<\/mo><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I=\\int_a^b f(x)\\,dx<\/annotation><\/semantics><\/math>\ndurch gewichtete Funktionswerte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><msub><mi>w<\/mi><mi>i<\/mi><\/msub><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Q=\\sum_i w_if(x_i)<\/annotation><\/semantics><\/math>.\nIntegriert man das Lagrange-Interpolationspolynom, erhält man Gewichte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>w<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><msubsup><mo>∫<\/mo><mi>a<\/mi><mi>b<\/mi><\/msubsup><msub><mi>L<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">w_i=\\int_a^b L_i(x)\\,dx<\/annotation><\/semantics><\/math>.\nFür zwei Endpunkte ist das Interpolationspolynom linear; seine\nIntegration ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T=(b-a)(f(a)+f(b))/2<\/annotation><\/semantics><\/math>.\nFür drei äquidistante Knoten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>,<\/mo><mi>m<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a,m=(a+b)/2,b<\/annotation><\/semantics><\/math>\nliefert die Integration der quadratischen Basis die Simpsonregel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>4<\/mn><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S=(b-a)(f(a)+4f(m)+f(b))/6<\/annotation><\/semantics><\/math>.<\/p>\n<p>Die Simpsonregel ist sogar für kubische Polynome exakt: Nach\nVerschiebung auf das symmetrische Intervall\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mi>h<\/mi><mo>,<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-h,h]<\/annotation><\/semantics><\/math>\nwerden die ungeraden Monome\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>3<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^3<\/annotation><\/semantics><\/math>\nsowohl exakt als auch durch die symmetrische Regel zu null integriert.\nDie Monome 1 und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^2<\/annotation><\/semantics><\/math>\nsind durch die Konstruktion exakt. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>4<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^4<\/annotation><\/semantics><\/math>\ngilt dies nicht mehr.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_036_DE.svg\"\nalt=\"Trapez- und Simpson-Interpolant für x hoch vier auf dem Einheitsintervall.\" />\n<figcaption aria-hidden=\"true\">Trapez- und Simpson-Interpolant für x\nhoch vier auf dem Einheitsintervall.<\/figcaption>\n<\/figure>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammengesetzte Regeln und Fehlergrenzen<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>≥<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n\\ge1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">h=(b-a)/n<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mi>a<\/mi><mo>+<\/mo><mi>i<\/mi><mi>h<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x_i=a+ih<\/annotation><\/semantics><\/math>\nlautet die zusammengesetzte Trapezregel<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mi>h<\/mi><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><mn>2<\/mn><\/mfrac><mo>+<\/mo><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mrow><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/munderover><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T_n=h\\left(\\frac{f(x_0)+f(x_n)}2+\\sum_{i=1}^{n-1}f(x_i)\\right).<\/annotation><\/semantics><\/math><\/p>\n<p>Für gerades\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>≥<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n\\ge2<\/annotation><\/semantics><\/math>\nist die zusammengesetzte Simpsonregel<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mfrac><mi>h<\/mi><mn>3<\/mn><\/mfrac><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>4<\/mn><munder><mo>∑<\/mo><mrow><mi>i<\/mi><mspace width=\"0.222em\"><\/mspace><mrow><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">g<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><\/mrow><\/munder><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>2<\/mn><munder><mo>∑<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>i<\/mi><mo>&lt;<\/mo><mi>n<\/mi><\/mrow><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mrow><mi>i<\/mi><mspace width=\"0.222em\"><\/mspace><mrow><mi mathvariant=\"normal\">g<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><\/mrow><\/mtd><\/mtr><\/mtable><\/munder><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>,<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S_n=\\frac h3\\left(f(x_0)+f(x_n)+4\\sum_{i\\ \\mathrm{ungerade}}f(x_i)+2\\sum_{\\substack{0&lt;i&lt;n\\\\i\\ \\mathrm{gerade}}}f(x_i)\\right),<\/annotation><\/semantics><\/math><\/p>\n<p>wobei die ungerade Summe nur innere Knoten umfasst. Unter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>∈<\/mo><msup><mi>C<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f\\in C^2([a,b])<\/annotation><\/semantics><\/math>\nbzw.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>∈<\/mo><msup><mi>C<\/mi><mn>4<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f\\in C^4([a,b])<\/annotation><\/semantics><\/math>\ngelten<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>I<\/mi><mo>−<\/mo><msub><mi>T<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mfrac><mrow><mi>b<\/mi><mo>−<\/mo><mi>a<\/mi><\/mrow><mn>12<\/mn><\/mfrac><msup><mi>h<\/mi><mn>2<\/mn><\/msup><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mo>″<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>I<\/mi><mo>−<\/mo><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mfrac><mrow><mi>b<\/mi><mo>−<\/mo><mi>a<\/mi><\/mrow><mn>180<\/mn><\/mfrac><msup><mi>h<\/mi><mn>4<\/mn><\/msup><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|I-T_n|\\le\\frac{b-a}{12}h^2\\max|f&#39;&#39;|,\\qquad |I-S_n|\\le\\frac{b-a}{180}h^4\\max|f^{(4)}|.<\/annotation><\/semantics><\/math><\/p>\n<p>Die erste Schranke folgt durch Integration des linearen\nInterpolationsrestes auf jedem Teilintervall:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>h<\/mi><\/msubsup><mi>t<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo>−<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>t<\/mi><mo>=<\/mo><msup><mi>h<\/mi><mn>3<\/mn><\/msup><mi>/<\/mi><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\int_0^h t(h-t)\\,dt=h^3/6<\/annotation><\/semantics><\/math>.\nFür Simpson kann man auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mi>h<\/mi><mo>,<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-h,h]<\/annotation><\/semantics><\/math>\nden Fehleroperator\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mi>I<\/mi><mo>−<\/mo><mi>S<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E=I-S<\/annotation><\/semantics><\/math>\nauf die Taylorformel mit Integralrest vierter Ordnung anwenden. Er\nannihiliert Polynome bis Grad 3; sein Peano-Kern ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mi>t<\/mi><msubsup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>3<\/mn><\/msubsup><mi>/<\/mi><mn>6<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">K(t)=E[(x-t)_+^3/6]<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>≤<\/mo><mi>t<\/mi><mo>≤<\/mo><mi>h<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0\\le t\\le h<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>−<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo>−<\/mo><mi>t<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>3<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>h<\/mi><mo>+<\/mo><mn>3<\/mn><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>72<\/mn><\/mrow><annotation encoding=\"application/x-tex\">K(t)=-(h-t)^3(h+3t)/72<\/annotation><\/semantics><\/math>,\nfür negative\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>t<\/mi><annotation encoding=\"application/x-tex\">t<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>K<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">K(-t)=K(t)<\/annotation><\/semantics><\/math>\ndurch Symmetrie und Polynomexaktheit. Der Kern ist nichtpositiv und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∫<\/mo><mi>K<\/mi><mo>=<\/mo><mi>−<\/mi><msup><mi>h<\/mi><mn>5<\/mn><\/msup><mi>/<\/mi><mn>90<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\int K=-h^5/90<\/annotation><\/semantics><\/math>.\nSomit ist der Fehler pro Doppelintervall höchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>h<\/mi><mn>5<\/mn><\/msup><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>/<\/mi><mn>90<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h^5\\max|f^{(4)}|/90<\/annotation><\/semantics><\/math>.\nAddition über\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n/2<\/annotation><\/semantics><\/math>\nDoppelintervalle liefert die angegebene Schranke.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gauß-Legendre-Quadratur<\/h2>\n<p>Bei Gauß-Legendre-Quadratur werden auch die Knoten optimiert. Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-1,1]<\/annotation><\/semantics><\/math>\nsuche eine symmetrische Regel mit Knoten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>±<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\pm c<\/annotation><\/semantics><\/math>\nund gleichem Gewicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>w<\/mi><annotation encoding=\"application/x-tex\">w<\/annotation><\/semantics><\/math>.\nExaktheit für 1 erfordert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>w<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2w=2<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">w=1<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^2<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2c^2=2/3<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">c=1/\\sqrt3<\/annotation><\/semantics><\/math>.\nUngerade Monome bis Grad 3 werden wegen Symmetrie exakt integriert.\nDamit gilt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><mn>1<\/mn><\/msubsup><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>x<\/mi><mo>≈<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_{-1}^1 f(x)\\,dx\\approx f(-1/\\sqrt3)+f(1/\\sqrt3).<\/annotation><\/semantics><\/math><\/p>\n<p>Allgemein auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[a,b]<\/annotation><\/semantics><\/math>\nsetze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=(a+b)/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>b<\/mi><mo>−<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d=(b-a)/2<\/annotation><\/semantics><\/math>;\ndie Näherung lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>m<\/mi><mo>−<\/mo><mi>d<\/mi><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>m<\/mi><mo>+<\/mo><mi>d<\/mi><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">d[f(m-d/\\sqrt3)+f(m+d/\\sqrt3)]<\/annotation><\/semantics><\/math>.\nDie allgemeine Gauß-Legendre-Regel mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\nKnoten verwendet Nullstellen des Legendre-Polynoms\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>k<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_k<\/annotation><\/semantics><\/math>\nund ist exakt für Polynome bis Grad\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>k<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2k-1<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>4<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^4<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-1,1]<\/annotation><\/semantics><\/math>\nliefert die Zweipunktregel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>/<\/mi><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2/9<\/annotation><\/semantics><\/math>\nstatt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>/<\/mi><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2/5<\/annotation><\/semantics><\/math>.\nExaktheit für niedrige Grade bedeutet also nicht Fehlerfreiheit für\nbeliebige Funktionen.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Konvergenzexperiment und Grenzen<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><msup><mi>x<\/mi><mn>4<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f=x^4<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I=1/5<\/annotation><\/semantics><\/math>.\nMit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=2<\/annotation><\/semantics><\/math>\nergeben sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>9<\/mn><mi>/<\/mi><mn>32<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T_2=9/32<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>5<\/mn><mi>/<\/mi><mn>24<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_2=5/24<\/annotation><\/semantics><\/math>,\nund mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=4<\/annotation><\/semantics><\/math>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mn>4<\/mn><\/msub><mo>=<\/mo><mn>77<\/mn><mi>/<\/mi><mn>384<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_4=77/384<\/annotation><\/semantics><\/math>.\nDie Simpsonfehler verhalten sich exakt wie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>16<\/mn><mo>:<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">16:1<\/annotation><\/semantics><\/math>.\nDer folgende Code ermöglicht weitere Experimente.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> quadrature(f, a, b, n, simpson<span class=\"op\">=<\/span><span class=\"va\">False<\/span>):<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> n <span class=\"op\">&lt;<\/span> <span class=\"dv\">1<\/span> <span class=\"kw\">or<\/span> (simpson <span class=\"kw\">and<\/span> n <span class=\"op\">%<\/span> <span class=\"dv\">2<\/span>):<\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;positive n, even for Simpson&quot;<\/span>)<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    h <span class=\"op\">=<\/span> (b<span class=\"op\">-<\/span>a)<span class=\"op\">/<\/span>n<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    y <span class=\"op\">=<\/span> [f(a<span class=\"op\">+<\/span>i<span class=\"op\">*<\/span>h) <span class=\"cf\">for<\/span> i <span class=\"kw\">in<\/span> <span class=\"bu\">range<\/span>(n<span class=\"op\">+<\/span><span class=\"dv\">1<\/span>)]<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> simpson:<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">return<\/span> h<span class=\"op\">/<\/span><span class=\"dv\">3<\/span><span class=\"op\">*<\/span>(y[<span class=\"dv\">0<\/span>]<span class=\"op\">+<\/span>y[<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>]<span class=\"op\">+<\/span><span class=\"bu\">sum<\/span>((<span class=\"dv\">4<\/span> <span class=\"cf\">if<\/span> i<span class=\"op\">%<\/span><span class=\"dv\">2<\/span> <span class=\"cf\">else<\/span> <span class=\"dv\">2<\/span>)<span class=\"op\">*<\/span>y[i]<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                                    <span class=\"cf\">for<\/span> i <span class=\"kw\">in<\/span> <span class=\"bu\">range<\/span>(<span class=\"dv\">1<\/span>,n)))<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> h<span class=\"op\">*<\/span>((y[<span class=\"dv\">0<\/span>]<span class=\"op\">+<\/span>y[<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>])<span class=\"op\">/<\/span><span class=\"dv\">2<\/span><span class=\"op\">+<\/span><span class=\"bu\">sum<\/span>(y[<span class=\"dv\">1<\/span>:<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>]))<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">for<\/span> n <span class=\"kw\">in<\/span> (<span class=\"dv\">2<\/span>, <span class=\"dv\">4<\/span>, <span class=\"dv\">8<\/span>, <span class=\"dv\">16<\/span>):<\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"bu\">print<\/span>(n, <span class=\"bu\">abs<\/span>(quadrature(<span class=\"kw\">lambda<\/span> x: x<span class=\"op\">**<\/span><span class=\"dv\">4<\/span>, <span class=\"dv\">0<\/span>, <span class=\"dv\">1<\/span>, n, <span class=\"va\">True<\/span>)<span class=\"op\">-<\/span><span class=\"fl\">0.2<\/span>))<\/span><\/code><\/pre><\/div>\n<p>Unter ausreichender Glattheit und im asymptotischen Bereich ist bei\nHalbierung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\ntypischerweise ein Fehlerfaktor 4 beziehungsweise 16 zu beobachten. Bei\nverschwindendem führendem Fehlerterm oder dominanter Rundung gilt dies\nnicht zwingend. Für eine unbekannte Lösung kann bei einer\nFehlerentwicklung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo>−<\/mo><msub><mi>Q<\/mi><mi>h<\/mi><\/msub><mo>=<\/mo><mi>C<\/mi><msup><mi>h<\/mi><mi>p<\/mi><\/msup><mo>+<\/mo><mi>o<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>h<\/mi><mi>p<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">I-Q_h=Ch^p+o(h^p)<\/annotation><\/semantics><\/math>\ndie Differenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>Q<\/mi><mrow><mi>h<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>−<\/mo><msub><mi>Q<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mn>2<\/mn><mi>p<\/mi><\/msup><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|Q_{h/2}-Q_h|/(2^p-1)<\/annotation><\/semantics><\/math>\nden feineren Fehler schätzen. Ein solcher Schätzer ist ohne weitere\nAnnahmen keine garantierte Schranke. Singularitäten und Sprünge\nverlangen angepasste Verfahren; bloße Verdopplung der Stützstellen ist\nkein Nachweis zuverlässiger Genauigkeit.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>T<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">T_2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>S<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">S_2<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^2<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bestimme eine Simpson-Fehlerschranke für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mi>x<\/mi><\/msup><annotation encoding=\"application/x-tex\">e^x<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=4<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wende die Zweipunkt-Gaußregel auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mn>3<\/mn><\/msup><mo>+<\/mo><mn>2<\/mn><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x^3+2x^2+1<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[-1,1]<\/annotation><\/semantics><\/math>\nan.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Zeige, dass die Zweipunkt-Gaußregel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">x^2<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,2]<\/annotation><\/semantics><\/math>\nexakt integriert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Eine Rechnung mit Simpson liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q<\/mi><mi>h<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0024<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q_h=1{,}0024<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q<\/mi><mrow><mi>h<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>00015<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q_{h/2}=1{,}00015<\/annotation><\/semantics><\/math>.\nSchätze den feineren Fehler unter angenommener vierter Ordnung.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T_2=3/8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_2=1/3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>e<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>180<\/mn><mo>⋅<\/mo><msup><mn>4<\/mn><mn>4<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>e<\/mi><mi>/<\/mi><mn>46080<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e/(180\\cdot4^4)=e/46080<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>+<\/mo><mn>4<\/mn><mi>/<\/mi><mn>3<\/mn><mo>=<\/mo><mn>10<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2+4/3=10/3<\/annotation><\/semantics><\/math>;\nder ungerade Term verschwindet.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mi>d<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=d=1<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mn>3<\/mn><\/msqrt><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn>8<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(1-1/\\sqrt3)^2+(1+1/\\sqrt3)^2=8/3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>00225<\/mn><mi>/<\/mi><mn>15<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>00015<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}00225/15=0{,}00015<\/annotation><\/semantics><\/math>;\ndies ist eine Schätzung unter der angegebenen Annahme.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://tobydriscoll.net/fnc-julia/localapprox/integration.html\">Driscoll/Braun\n– Fundamentals of Numerical Computation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §5.6 · Zuletzt abgerufen:\n2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://dlmf.nist.gov/3.5\">NIST DLMF – Quadrature<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> ·\n§3.5(v) · Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft:\n2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M7-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M7-L3 – Runge–Kutta-Verfahren und numerische Stabilität<\/h1>\n<p><strong>Kursbereich:<\/strong> M7 – Numerik und Optimierung<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L9&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L9<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L8&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L8<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Numerische Vertiefung des gemeinsamen\nBachelor-Kerns<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du berechnest einen klassischen Runge–Kutta-Schritt, unterscheidest\nlokale und globale Fehlerordnung, leitest die Stabilitätsfunktion auf\neiner linearen Testgleichung her und begründest, warum steife Probleme\nbesondere Integratoren erfordern können.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Ein-Schritt-Verfahren und RK4<\/h2>\n<p>Gegeben sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=f(t,y)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>y<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">y(t_0)=y_0<\/annotation><\/semantics><\/math>,\nmit einer hinreichend glatten rechten Seite. Für einen Schritt der Länge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h&gt;0<\/annotation><\/semantics><\/math>\nberechnet Euler die Näherung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>,<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y_{n+1}=y_n+hf(t_n,y_n)<\/annotation><\/semantics><\/math>.\nEin explizites Runge–Kutta-Verfahren verwendet mehrere Steigungen\ninnerhalb desselben Schritts. Beim klassischen vierstufigen Verfahren\ngilt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mtable><mtr><mtd columnalign=\"right\" class=\"text-right\"><msub><mi>k<\/mi><mn>1<\/mn><\/msub><\/mtd><mtd columnalign=\"left\"><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>,<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><\/mtd><\/mtr><mtr><mtd columnalign=\"right\" class=\"text-right\"><msub><mi>k<\/mi><mn>2<\/mn><\/msub><\/mtd><mtd columnalign=\"left\"><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><msub><mi>k<\/mi><mn>1<\/mn><\/msub><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><\/mtd><\/mtr><mtr><mtd columnalign=\"right\" class=\"text-right\"><msub><mi>k<\/mi><mn>3<\/mn><\/msub><\/mtd><mtd columnalign=\"left\"><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><msub><mi>k<\/mi><mn>2<\/mn><\/msub><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><\/mtd><\/mtr><mtr><mtd columnalign=\"right\" class=\"text-right\"><msub><mi>k<\/mi><mn>4<\/mn><\/msub><\/mtd><mtd columnalign=\"left\"><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mo>,<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><msub><mi>k<\/mi><mn>3<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><\/mtd><\/mtr><mtr><mtd columnalign=\"right\" class=\"text-right\"><msub><mi>y<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><\/mtd><mtd columnalign=\"left\"><mo>=<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>k<\/mi><mn>1<\/mn><\/msub><mo>+<\/mo><mn>2<\/mn><msub><mi>k<\/mi><mn>2<\/mn><\/msub><mo>+<\/mo><mn>2<\/mn><msub><mi>k<\/mi><mn>3<\/mn><\/msub><mo>+<\/mo><msub><mi>k<\/mi><mn>4<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>6<\/mn><mi>.<\/mi><\/mtd><\/mtr><\/mtable><annotation encoding=\"application/x-tex\">\\begin{aligned}k_1&amp;=f(t_n,y_n),\\\\ k_2&amp;=f(t_n+h/2,y_n+hk_1/2),\\\\ k_3&amp;=f(t_n+h/2,y_n+hk_2/2),\\\\ k_4&amp;=f(t_n+h,y_n+hk_3),\\\\ y_{n+1}&amp;=y_n+h(k_1+2k_2+2k_3+k_4)/6.\\end{aligned}<\/annotation><\/semantics><\/math><\/p>\n<p>Die\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>k<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">k_i<\/annotation><\/semantics><\/math>\nsind Steigungen, keine bereits mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\nmultiplizierten Inkremente. Die mittleren Stufen verwenden\nunterschiedliche Zustandsschätzungen. Das Verfahren ist explizit: Jede\nStufe hängt nur von früheren Stufen ab. Beispiel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=y<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_0=1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=1/2<\/annotation><\/semantics><\/math>:\nDie Steigungen sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><mi>/<\/mi><mn>4<\/mn><mo>,<\/mo><mn>21<\/mn><mi>/<\/mi><mn>16<\/mn><mo>,<\/mo><mn>53<\/mn><mi>/<\/mi><mn>32<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1,5/4,21/16,53/32<\/annotation><\/semantics><\/math>.\nDer neue Wert ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>211<\/mn><mi>/<\/mi><mn>128<\/mn><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>6484375<\/mn><\/mrow><annotation encoding=\"application/x-tex\">211/128=1{,}6484375<\/annotation><\/semantics><\/math>,\nwährend\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>6487213<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e^{1/2}\\approx1{,}6487213<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lokaler Defekt und globale Ordnung<\/h2>\n<p>Für ein Verfahren der Ordnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nist der unskalierte lokale Defekt bei Start am exakten Wert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>h<\/mi><mrow><mi>p<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">O(h^{p+1})<\/annotation><\/semantics><\/math>.\nDer globale Fehler auf einem festen Zeitintervall ist unter geeigneten\nGlattheits- und Lipschitzannahmen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>h<\/mi><mi>p<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">O(h^p)<\/annotation><\/semantics><\/math>.\nFür RK4 ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=4<\/annotation><\/semantics><\/math>,\nfür Euler\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=1<\/annotation><\/semantics><\/math>.\nEine Begründung der Übertragung: Schreibe den Schritt als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Φ<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Phi_h(t,y)<\/annotation><\/semantics><\/math>.\nGilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi mathvariant=\"normal\">Φ<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>u<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msub><mi mathvariant=\"normal\">Φ<\/mi><mi>h<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>L<\/mi><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>u<\/mi><mo>−<\/mo><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\Phi_h(t,u)-\\Phi_h(t,v)|\\le(1+Lh)|u-v|<\/annotation><\/semantics><\/math>\nund ist der lokale Defekt durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><msup><mi>h<\/mi><mrow><mi>p<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Ch^{p+1}<\/annotation><\/semantics><\/math>\nbeschränkt, dann folgt für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>e<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">e_n=|y(t_n)-y_n|<\/annotation><\/semantics><\/math>\ndie Rekursion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>e<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>≤<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>L<\/mi><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>e<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><mi>C<\/mi><msup><mi>h<\/mi><mrow><mi>p<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">e_{n+1}\\le(1+Lh)e_n+Ch^{p+1}<\/annotation><\/semantics><\/math>.\nIteration bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>e<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e_0=0<\/annotation><\/semantics><\/math>\nliefert für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">L&gt;0<\/annotation><\/semantics><\/math>\ndie Schranke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><msup><mi>h<\/mi><mi>p<\/mi><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>e<\/mi><mrow><mi>L<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><msub><mi>t<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>L<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Ch^p(e^{L(t_n-t_0)}-1)/L<\/annotation><\/semantics><\/math>;\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">L=0<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><msub><mi>t<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>h<\/mi><mi>p<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">C(t_n-t_0)h^p<\/annotation><\/semantics><\/math>.\nDie vierte Ordnung des klassischen Verfahrens für allgemeine glatte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nfolgt aus dem Taylorvergleich der Stufen bis Grad vier (hier nicht\nvollständig hergeleitet). Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>λ<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=\\lambda y<\/annotation><\/semantics><\/math>\nlässt sie sich direkt am Stabilitätspolynom nachvollziehen. Ein\neinzelner Test der linearen Gleichung beweist die allgemeine Ordnung\nnicht.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Absolute Stabilität und Steifigkeit<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>λ<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=\\lambda y<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><mi>h<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">z=h\\lambda<\/annotation><\/semantics><\/math>,\nist die exakte Verstärkung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mi>z<\/mi><\/msup><annotation encoding=\"application/x-tex\">e^z<\/annotation><\/semantics><\/math>.\nEinsetzen der vier Stufen ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">y_{n+1}=R(z)y_n<\/annotation><\/semantics><\/math>\nmit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>+<\/mo><mi>z<\/mi><mo>+<\/mo><msup><mi>z<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo>+<\/mo><msup><mi>z<\/mi><mn>3<\/mn><\/msup><mi>/<\/mi><mn>6<\/mn><mo>+<\/mo><msup><mi>z<\/mi><mn>4<\/mn><\/msup><mi>/<\/mi><mn>24<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R(z)=1+z+z^2/2+z^3/6+z^4/24.<\/annotation><\/semantics><\/math><\/p>\n<p>Damit ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>n<\/mi><\/msup><msub><mi>y<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">y_n=R(z)^ny_0<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|R(z)|\\le1<\/annotation><\/semantics><\/math>\nbleiben die Werte beschränkt; bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|R(z)|&lt;1<\/annotation><\/semantics><\/math>\nklingen sie ab. Euler besitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>E<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>+<\/mo><mi>z<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R_E(z)=1+z<\/annotation><\/semantics><\/math>\nund die Stabilitätsscheibe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>z<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|z+1|\\le1<\/annotation><\/semantics><\/math>.\nAuf der negativen reellen Achse reicht RK4 ungefähr von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>2<\/mn><mo>,<\/mo><mn>7853<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-2{,}7853<\/annotation><\/semantics><\/math>\nbis 0, Euler nur von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-2<\/annotation><\/semantics><\/math>\nbis 0. Auf der Grenze ist Beschränktheit nicht gleich Abklingen. Die\nRK4-Grenze folgt aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>r<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R(-r)=1<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>r<\/mi><mn>3<\/mn><\/msup><mo>−<\/mo><mn>4<\/mn><msup><mi>r<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mn>12<\/mn><mi>r<\/mi><mo>−<\/mo><mn>24<\/mn><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">r^3-4r^2+12r-24=0<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">r&gt;0<\/annotation><\/semantics><\/math>;\ndieses Polynom ist streng monoton. Tatsächlich ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>24<\/mn><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>r<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>r<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><mn>2<\/mn><mi>r<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mn>8<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>r<\/mi><mo>−<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mn>6<\/mn><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">24R(-r)=(r^2-2r)^2+8(r-3/2)^2+6&gt;0<\/annotation><\/semantics><\/math>.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_037_DE.svg\"\nalt=\"Stabilitätsgebiete von Euler und RK4 mit Testpunkten −3 und −2,5.\" />\n<figcaption aria-hidden=\"true\">Stabilitätsgebiete von Euler und RK4 mit\nTestpunkten −3 und −2,5.<\/figcaption>\n<\/figure>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=-100<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>03<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=0{,}03<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><mi>−<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">z=-3<\/annotation><\/semantics><\/math>;\nRK4 verstärkt mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>11<\/mn><mi>/<\/mi><mn>8<\/mn><mo>&gt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">11/8&gt;1<\/annotation><\/semantics><\/math>,\nobwohl die exakte Lösung abklingt. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>025<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=0{,}025<\/annotation><\/semantics><\/math>\nliegt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><mi>−<\/mi><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">z=-2{,}5<\/annotation><\/semantics><\/math>\nim RK4-Stabilitätsbereich, aber außerhalb des Eulerbereichs. Stabilität\ngarantiert keine hohe Genauigkeit. Ein steifes System wie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>u<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>−<\/mi><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">u&#39;=-u<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>v<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>−<\/mi><mn>1000<\/mn><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v&#39;=-1000v<\/annotation><\/semantics><\/math>\nbesitzt sehr verschiedene Zeitskalen. Auch wenn die schnelle Komponente\nschon klein ist, kann sie die explizite Schrittweite beschränken.\nRückwärts-Euler besitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>B<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">R_B(z)=1/(1-z)<\/annotation><\/semantics><\/math>\nund ist für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Re<\/mi><mo>&#8289;<\/mo><\/mrow><mi>z<\/mi><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Re}z\\le0<\/annotation><\/semantics><\/math>\nabsolut stabil (A-stabil); für stark negative reelle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>z<\/mi><annotation encoding=\"application/x-tex\">z<\/annotation><\/semantics><\/math>\ngeht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>B<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_B<\/annotation><\/semantics><\/math>\ngegen null. Der Preis ist im Allgemeinen das Lösen eines impliziten\nGleichungssystems.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Experiment und Verfahrenswahl<\/h2>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> math <span class=\"im\">import<\/span> exp<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> rk4(f, t, y, h):<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    k1 <span class=\"op\">=<\/span> f(t, y)<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    k2 <span class=\"op\">=<\/span> f(t<span class=\"op\">+<\/span>h<span class=\"op\">/<\/span><span class=\"dv\">2<\/span>, y<span class=\"op\">+<\/span>h<span class=\"op\">*<\/span>k1<span class=\"op\">/<\/span><span class=\"dv\">2<\/span>)<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    k3 <span class=\"op\">=<\/span> f(t<span class=\"op\">+<\/span>h<span class=\"op\">/<\/span><span class=\"dv\">2<\/span>, y<span class=\"op\">+<\/span>h<span class=\"op\">*<\/span>k2<span class=\"op\">/<\/span><span class=\"dv\">2<\/span>)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    k4 <span class=\"op\">=<\/span> f(t<span class=\"op\">+<\/span>h, y<span class=\"op\">+<\/span>h<span class=\"op\">*<\/span>k3)<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> y<span class=\"op\">+<\/span>h<span class=\"op\">*<\/span>(k1<span class=\"op\">+<\/span><span class=\"dv\">2<\/span><span class=\"op\">*<\/span>k2<span class=\"op\">+<\/span><span class=\"dv\">2<\/span><span class=\"op\">*<\/span>k3<span class=\"op\">+<\/span>k4)<span class=\"op\">/<\/span><span class=\"dv\">6<\/span><\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> solve(f, a, b, y, n):<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> n <span class=\"op\">&lt;<\/span> <span class=\"dv\">1<\/span> <span class=\"kw\">or<\/span> b <span class=\"op\">&lt;=<\/span> a:<\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;positive step count and interval required&quot;<\/span>)<\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    h <span class=\"op\">=<\/span> (b<span class=\"op\">-<\/span>a)<span class=\"op\">/<\/span>n<\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">for<\/span> i <span class=\"kw\">in<\/span> <span class=\"bu\">range<\/span>(n):<\/span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        y <span class=\"op\">=<\/span> rk4(f, a<span class=\"op\">+<\/span>i<span class=\"op\">*<\/span>h, y, h)<\/span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> y<\/span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">for<\/span> n <span class=\"kw\">in<\/span> (<span class=\"dv\">10<\/span>, <span class=\"dv\">20<\/span>, <span class=\"dv\">40<\/span>, <span class=\"dv\">80<\/span>):<\/span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"bu\">print<\/span>(n, <span class=\"bu\">abs<\/span>(solve(<span class=\"kw\">lambda<\/span> t,y: y, <span class=\"dv\">0<\/span>, <span class=\"dv\">1<\/span>, <span class=\"dv\">1<\/span>, n)<span class=\"op\">-<\/span>exp(<span class=\"dv\">1<\/span>)))<\/span><\/code><\/pre><\/div>\n<p>Auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=y<\/annotation><\/semantics><\/math>\nnähert sich der Quotient der Endpunktfehler bei halbierter Schrittweite\ndem Wert 16. Bei sehr kleinen Schritten können Rundungsfehler\ndominieren. Für einen lokalen Fehlerschätzer kann man einen Schritt der\nLänge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\nmit zwei halben Schritten vergleichen. Bei glatter Lösung und führendem\nDefektterm der Ordnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>h<\/mi><mn>5<\/mn><\/msup><annotation encoding=\"application/x-tex\">h^5<\/annotation><\/semantics><\/math>\nschätzt der Betrag ihrer Differenz geteilt durch 15 den lokalen Fehler\nder zwei halben Schritte. Dies ist keine globale Fehlergarantie. In\nrealen Anwendungen sind eingebettete RK-Verfahren mit adaptiver\nSchrittsteuerung üblich; bei Steifigkeit sind geeignete implizite\nVerfahren vorzuziehen. Neben Toleranzen sind Modellfehler, Ereignisse,\nSingularitäten und Erhaltungsgrößen zu prüfen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne einen RK4-Schritt für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_0=3<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=1/4<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Leite\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">R(z)<\/annotation><\/semantics><\/math>\naus den vier RK4-Stufen für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>y<\/mi><mo>′<\/mo><\/msup><mo>=<\/mo><mi>λ<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y&#39;=\\lambda y<\/annotation><\/semantics><\/math>\nher.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Prüfe Euler und RK4 auf Abklingen bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><mi>−<\/mi><mn>5<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">z=-5/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1000<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=-1000<\/annotation><\/semantics><\/math>:\nBestimme die ungefähre maximale RK4-Schrittweite für\nBeschränktheit.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Begründe die globale Ordnung vier aus einem lokalen Defekt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>h<\/mi><mn>5<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">O(h^5)<\/annotation><\/semantics><\/math>\nund einer Lipschitz-Schranke des Schritts.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Alle Steigungen sind 2;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>7<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_1=7/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><msub><mi>k<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mi>z<\/mi><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">hk_1=zy<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><msub><mi>k<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>z<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">hk_2=z(1+z/2)y<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><msub><mi>k<\/mi><mn>3<\/mn><\/msub><mo>=<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>z<\/mi><mi>/<\/mi><mn>2<\/mn><mo>+<\/mo><msup><mi>z<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">hk_3=z(1+z/2+z^2/4)y<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><msub><mi>k<\/mi><mn>4<\/mn><\/msub><mo>=<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>z<\/mi><mo>+<\/mo><msup><mi>z<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo>+<\/mo><msup><mi>z<\/mi><mn>3<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">hk_4=z(1+z+z^2/2+z^3/4)y<\/annotation><\/semantics><\/math>.\nGewichtete Summe ergibt das angegebene Polynom.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Euler:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>−<\/mi><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&gt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|-3/2|&gt;1<\/annotation><\/semantics><\/math>.\nRK4:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>5<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>83<\/mn><mi>/<\/mi><mn>128<\/mn><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R(-5/2)=83/128&lt;1<\/annotation><\/semantics><\/math>\nund positiv; nur RK4 klingt ab.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>≤<\/mo><mn>2<\/mn><mo>,<\/mo><mn>7853<\/mn><mi>/<\/mi><mn>1000<\/mn><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0027853<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h\\le 2{,}7853/1000\\approx0{,}0027853<\/annotation><\/semantics><\/math>;\nfür Abklingen strikt darunter, bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h&gt;0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Die Fehlerrekursion summiert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">O(1/h)<\/annotation><\/semantics><\/math>\nlokale Defekte mit auf dem festen Zeitintervall beschränkten\nVerstärkungsfaktoren. Daher\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>h<\/mi><mn>4<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">O(h^4)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://tobydriscoll.net/fnc-julia/ivp/rk.html\">Driscoll/Braun –\nFundamentals of Numerical Computation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §6.4 · Zuletzt abgerufen:\n2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://tobydriscoll.net/fnc-julia/diffusion/absstab-diffusion.html\">Driscoll/Braun\n– Fundamentals of Numerical Computation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §11.3 · Zuletzt abgerufen:\n2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M7-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M7-L4 – KKT-Bedingungen und aktive Nebenbedingungen<\/h1>\n<p><strong>Kursbereich:<\/strong> M7 – Numerik und Optimierung<\/p>\n<p><strong>Niveau:<\/strong> Masterorientierung · Fortgeschrittene\nVertiefung<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M3&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M3-L6<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Vertiefung auf Master-Niveau<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du formulierst die Karush–Kuhn–Tucker-Bedingungen (KKT) für glatte\nOptimierungsprobleme, bestimmst aktive Nebenbedingungen und\nMultiplikatoren, beweist die globale Optimalität im konvexen Fall und\nerkennst, wann KKT weder einen Optimalitätsnachweis noch eine notwendige\nBedingung liefert.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lagrange-Funktion und KKT-System<\/h2>\n<p>Betrachte die Minimierung einer differenzierbaren Funktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>:<\/mo><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mi>n<\/mi><\/msup><mo>→<\/mo><mi mathvariant=\"double-struck\">ℝ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f:\\mathbb R^n\\to\\mathbb R<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g_i(x)\\le0<\/annotation><\/semantics><\/math>\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><mi>m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">i=1,\\dots,m<\/annotation><\/semantics><\/math>)\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_j(x)=0<\/annotation><\/semantics><\/math>\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><mi>q<\/mi><\/mrow><annotation encoding=\"application/x-tex\">j=1,\\dots,q<\/annotation><\/semantics><\/math>),\nebenfalls differenzierbar. Die Vorzeichenkonvention bestimmt die\nLagrange-Funktion<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"script\">ℒ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>λ<\/mi><mo>,<\/mo><mi>ν<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><munder><mo>∑<\/mo><mi>i<\/mi><\/munder><msub><mi>λ<\/mi><mi>i<\/mi><\/msub><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><munder><mo>∑<\/mo><mi>j<\/mi><\/munder><msub><mi>ν<\/mi><mi>j<\/mi><\/msub><msub><mi>a<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal L(x,\\lambda,\\nu)=f(x)+\\sum_i\\lambda_i g_i(x)+\\sum_j\\nu_j a_j(x).<\/annotation><\/semantics><\/math><\/p>\n<p>Die vier KKT-Bedingungen lauten:<\/p>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\">Primale Zulässigkeit:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g_i(x)\\le0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a_j(x)=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\">Duale Zulässigkeit:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>i<\/mi><\/msub><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_i\\ge0<\/annotation><\/semantics><\/math>;\ndie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>ν<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\nu_j<\/annotation><\/semantics><\/math>\nsind frei.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\">Stationarität:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∇<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><msub><mi>λ<\/mi><mi>i<\/mi><\/msub><mi>∇<\/mi><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><msub><mo>∑<\/mo><mi>j<\/mi><\/msub><msub><mi>ν<\/mi><mi>j<\/mi><\/msub><mi>∇<\/mi><msub><mi>a<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nabla f(x)+\\sum_i\\lambda_i\\nabla g_i(x)+\\sum_j\\nu_j\\nabla a_j(x)=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\">Komplementärer Schlupf:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>i<\/mi><\/msub><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_i g_i(x)=0<\/annotation><\/semantics><\/math>\nfür jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>i<\/mi><annotation encoding=\"application/x-tex\">i<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ul>\n<p>Eine Ungleichung ist aktiv, wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g_i(x)=0<\/annotation><\/semantics><\/math>.\nEine strikt inaktive Bedingung hat zwingend\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_i=0<\/annotation><\/semantics><\/math>.\nUmgekehrt kann eine aktive Bedingung durchaus einen verschwindenden\nMultiplikator besitzen. Geometrisch kompensiert die negative\nZielfunktionssteigung am regulären Minimum die Normale der aktiven\nBedingungen; sie liegt im Kegel der aktiven Ungleichungsgradienten plus\ndem linearen Raum der Gleichungsgradienten.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aktive Mengen und Rechenbeispiel<\/h2>\n<p>Minimiere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>y<\/mi><mo>−<\/mo><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f(x,y)=((x-2)^2+(y-2)^2)/2<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo>=<\/mo><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>−<\/mo><mn>2<\/mn><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g=x+y-2\\le0<\/annotation><\/semantics><\/math>.\nDas unbeschränkte Minimum\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(2,2)<\/annotation><\/semantics><\/math>\nist unzulässig. Ist die Bedingung aktiv, gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x+y=2<\/annotation><\/semantics><\/math>.\nStationarität ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>−<\/mo><mn>2<\/mn><mo>+<\/mo><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x-2+\\lambda=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>−<\/mo><mn>2<\/mn><mo>+<\/mo><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y-2+\\lambda=0<\/annotation><\/semantics><\/math>;\ndamit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mi>y<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=y=1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=1<\/annotation><\/semantics><\/math>.\nAlle vier Bedingungen sind erfüllt. Der Zielfunktionswert ist 1. Die\nHesse-Matrix von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nist die Einheitsmatrix; das Problem ist streng konvex mit affiner\nNebenbedingung, also ist dies das eindeutige globale Minimum.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_038_DE.svg\"\nalt=\"Niveaulinien, zulässiger Halbraum und negative Zielfunktionssteigung am Optimum.\" />\n<figcaption aria-hidden=\"true\">Niveaulinien, zulässiger Halbraum und\nnegative Zielfunktionssteigung am Optimum.<\/figcaption>\n<\/figure>\n<p>Allgemeiner für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mi>a<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>y<\/mi><mo>−<\/mo><mi>b<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f=((x-a)^2+(y-b)^2)/2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>+<\/mo><mi>y<\/mi><mo>≤<\/mo><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x+y\\le c<\/annotation><\/semantics><\/math>\nfolgt durch Fallunterscheidung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mo>−<\/mo><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=\\max(0,(a+b-c)/2)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mi>a<\/mi><mo>−<\/mo><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x=a-\\lambda<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mi>b<\/mi><mo>−<\/mo><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y=b-\\lambda<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mo>=<\/mo><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">a+b=c<\/annotation><\/semantics><\/math>\nist die Bedingung aktiv, aber\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0<\/annotation><\/semantics><\/math>.\nDas Beispiel zeigt den Kern einer Active-Set-Strategie: Man nimmt eine\naktive Menge an, löst das Gleichungssystem und verwirft Kandidaten mit\nnegativer dualer Variable oder verletzter primaler Nebenbedingung. Bei\nvielen Nebenbedingungen ist naive Enumeration teuer.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Notwendigkeit und Hinreichendheit<\/h2>\n<p>An einem lokalen Minimum liefern die KKT-Bedingungen unter einer\ngeeigneten Regularitätsbedingung notwendige Bedingungen. Eine\nhinreichende solche Bedingung ist LICQ: Die Gradienten der Gleichungen\nund aller aktiven Ungleichungen sind linear unabhängig. Ohne Regularität\nist die Existenz von Multiplikatoren nicht gesichert.<\/p>\n<p>Für konvexe differenzierbare\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>,<\/mo><msub><mi>g<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">f,g_i<\/annotation><\/semantics><\/math>\nund affine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>a<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">a_j<\/annotation><\/semantics><\/math>\nsind erfüllte KKT-Bedingungen dagegen ohne zusätzliche\nRegularitätsannahme hinreichend für globale Optimalität: Bei festen\nzulässigen Multiplikatoren ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">ℒ<\/mi><annotation encoding=\"application/x-tex\">\\mathcal L<\/annotation><\/semantics><\/math>\nkonvex in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>.\nStationarität macht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mo>*<\/mo><\/msup><annotation encoding=\"application/x-tex\">x^*<\/annotation><\/semantics><\/math>\nzu einem globalen Minimierer von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">ℒ<\/mi><annotation encoding=\"application/x-tex\">\\mathcal L<\/annotation><\/semantics><\/math>.\nFür jeden primal zulässigen Punkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>z<\/mi><annotation encoding=\"application/x-tex\">z<\/annotation><\/semantics><\/math>\ngilt wegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ<\/mi><mi>i<\/mi><\/msub><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda_i\\ge0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g_i(z)\\le0<\/annotation><\/semantics><\/math>:<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≥<\/mo><mi mathvariant=\"script\">ℒ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo>,<\/mo><mi>λ<\/mi><mo>,<\/mo><mi>ν<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≥<\/mo><mi mathvariant=\"script\">ℒ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo>,<\/mo><mi>λ<\/mi><mo>,<\/mo><mi>ν<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f(z)\\ge\\mathcal L(z,\\lambda,\\nu)\\ge\\mathcal L(x^*,\\lambda,\\nu)=f(x^*).<\/annotation><\/semantics><\/math><\/p>\n<p>Die letzte Gleichheit folgt aus komplementärem Schlupf und den\nGleichungsbedingungen. Für konvexe Probleme auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi mathvariant=\"double-struck\">ℝ<\/mi><mi>n<\/mi><\/msup><annotation encoding=\"application/x-tex\">\\mathbb R^n<\/annotation><\/semantics><\/math>\nmit endlichem erreichtem Optimalwert sichert ein strikt zulässiger Punkt\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo>&lt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g_i&lt;0<\/annotation><\/semantics><\/math>,\nalle Gleichungen erfüllt; Slater-Bedingung) die Existenz geeigneter\nMultiplikatoren. In diesem Fall ist KKT notwendig und hinreichend.\nStrikte Konvexität von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nsichert bei Existenz des Minimums dessen Eindeutigkeit, nicht zwingend\neindeutige Multiplikatoren.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gegenbeispiele und numerische Kontrolle<\/h2>\n<p>Nichtkonvex: Minimiere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><msup><mi>x<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">-x^2<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><mn>1<\/mn><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x^2-1\\le0<\/annotation><\/semantics><\/math>.\nDer Punkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0<\/annotation><\/semantics><\/math>\nerfüllt KKT, ist aber ein striktes lokales Maximum; die globalen Minima\nliegen bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mi>±<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=\\pm1<\/annotation><\/semantics><\/math>.\nFehlende Regularität: Minimiere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f=x<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x^2\\le0<\/annotation><\/semantics><\/math>.\nDer einzige zulässige Punkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=0<\/annotation><\/semantics><\/math>\nist optimal, aber die Stationarität würde\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>+<\/mo><mi>λ<\/mi><mo>⋅<\/mo><mn>0<\/mn><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1+\\lambda\\cdot0=0<\/annotation><\/semantics><\/math>\nverlangen. Kein Multiplikator existiert. Slater und LICQ versagen.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> project_halfplane(a, b, c):<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"co\"># x+y &lt;= c<\/span><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    lam <span class=\"op\">=<\/span> <span class=\"bu\">max<\/span>(<span class=\"dv\">0<\/span>, (a<span class=\"op\">+<\/span>b<span class=\"op\">-<\/span>c)<span class=\"op\">/<\/span><span class=\"dv\">2<\/span>)<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> a<span class=\"op\">-<\/span>lam, b<span class=\"op\">-<\/span>lam, lam<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>x, y, lam <span class=\"op\">=<\/span> project_halfplane(<span class=\"dv\">2<\/span>, <span class=\"dv\">2<\/span>, <span class=\"dv\">2<\/span>)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">assert<\/span> (x, y, lam) <span class=\"op\">==<\/span> (<span class=\"dv\">1<\/span>, <span class=\"dv\">1<\/span>, <span class=\"dv\">1<\/span>)<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">assert<\/span> x<span class=\"op\">+<\/span>y <span class=\"op\">&lt;=<\/span> <span class=\"dv\">2<\/span> <span class=\"kw\">and<\/span> lam <span class=\"op\">&gt;=<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">and<\/span> lam<span class=\"op\">*<\/span>(x<span class=\"op\">+<\/span>y<span class=\"op\">-<\/span><span class=\"dv\">2<\/span>) <span class=\"op\">==<\/span> <span class=\"dv\">0<\/span><\/span><\/code><\/pre><\/div>\n<p>Bei numerischer Optimierung sollte man getrennt Residuen messen:\nmaximale Ungleichungsverletzung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mi>i<\/mi><\/msub><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><msub><mi>g<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\max_i\\max(0,g_i)<\/annotation><\/semantics><\/math>,\nGleichungsnorm, maximale negative duale Komponente, Stationaritätsnorm\nund maximale absolute Komplementaritätsprodukte. Leere Mengen tragen\njeweils null bei. Kleine Residuen sind toleranz- und skalierungsabhängig\nund bei nichtkonvexen Problemen kein globales Optimalitätszertifikat. Im\nkonvexen Fall kann eine rigorose duale Schranke zusätzlich die\nZielfunktionslücke begrenzen. Für das Projektionsbeispiel ist bei\ngeänderter Schranke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>c<\/mi><annotation encoding=\"application/x-tex\">c<\/annotation><\/semantics><\/math>\nder optimale Wert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mi>a<\/mi><mo>+<\/mo><mi>b<\/mi><mo>−<\/mo><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v(c)=(\\max(0,a+b-c))^2/4<\/annotation><\/semantics><\/math>;\nseine Ableitung ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">-\\lambda<\/annotation><\/semantics><\/math>.\nDiese Sensitivitätsaussage folgt hier unmittelbar aus der expliziten\nFormel und darf nicht ohne Voraussetzungen verallgemeinert werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Minimiere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mn>3<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(x-3)^2/2<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x\\le1<\/annotation><\/semantics><\/math>\nund finde den Multiplikator.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Löse die Projektion mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>b<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mi>c<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=1,b=0,c=3<\/annotation><\/semantics><\/math>;\nist die Bedingung aktiv?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Löse sie mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>b<\/mi><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mi>c<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=1,b=2,c=3<\/annotation><\/semantics><\/math>;\nwas zeigt der Multiplikator?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Zeige, dass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=0<\/annotation><\/semantics><\/math>\nbei Minimierung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nunter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mn>2<\/mn><\/msup><mo>≤<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x^2\\le0<\/annotation><\/semantics><\/math>\nkein KKT-Punkt ist.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Beweise für ein konvexes Problem, dass jeder KKT-Punkt global\noptimal ist, und nenne die benötigten Annahmen.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=2<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>−<\/mo><mn>3<\/mn><mo>+<\/mo><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x-3+\\lambda=0<\/annotation><\/semantics><\/math>\nund komplementärer Schlupf.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>,<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(x,y)=(1,0)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo>=<\/mo><mi>−<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g=-2<\/annotation><\/semantics><\/math>,\ninaktiv.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,2)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0<\/annotation><\/semantics><\/math>;\naktive Bedingung mit verschwindendem Multiplikator.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Der Gradient der Nebenbedingung ist null;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>+<\/mo><mn>2<\/mn><mi>λ<\/mi><mi>x<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1+2\\lambda x=1<\/annotation><\/semantics><\/math>\nkann bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=0<\/annotation><\/semantics><\/math>\nnicht verschwinden.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Konvexe differenzierbare Zielfunktion und Ungleichungen, affine\nGleichungen, primale und duale Zulässigkeit, Stationarität und\nKomplementarität. Die konvexe Lagrange-Funktion hat bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mo>*<\/mo><\/msup><annotation encoding=\"application/x-tex\">x^*<\/annotation><\/semantics><\/math>\nein Minimum und ist für alle zulässigen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>z<\/mi><annotation encoding=\"application/x-tex\">z<\/annotation><\/semantics><\/math>\nhöchstens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(z)<\/annotation><\/semantics><\/math>;\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mo>*<\/mo><\/msup><annotation encoding=\"application/x-tex\">x^*<\/annotation><\/semantics><\/math>\nstimmt sie mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>x<\/mi><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(x^*)<\/annotation><\/semantics><\/math>\nüberein.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://see.stanford.edu/materials/lsocoee364a/transcripts/ConvexOptimizationI-Lecture09.html\">Stanford\nEE364A – Stephen Boyd, Convex Optimization I<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Lecture 9, KKT and\nSlater · Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft:\n2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>"};
